WHITE = "W"
BLACK = "B"
NONE = ""


class Board:
    """Count territories of each player in a Go game

    Args:
        board (list[str]): A two-dimensional Go board
    """

    def __init__(self, board):
        self.board = board

    def _in_bounds(self, x, y):
        return (
            0 <= y < len(self.board)
            and 0 <= x < len(self.board[y])
        )

    def _neighbors(self, x, y):
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if self._in_bounds(nx, ny):
                yield nx, ny

    def _flood(self, x, y):
        """Return the set of empty intersections reachable from (x, y)."""
        region = set()
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in region or self.board[cy][cx] != " ":
                continue
            region.add((cx, cy))
            stack.extend(self._neighbors(cx, cy))
        return region

    def _owner(self, region):
        """Determine the owner of an empty region from its boundary stones."""
        owners = set()
        for x, y in region:
            for nx, ny in self._neighbors(x, y):
                stone = self.board[ny][nx]
                if stone != " ":
                    owners.add(stone)
        if owners == {BLACK}:
            return BLACK
        if owners == {WHITE}:
            return WHITE
        return NONE

    def territory(self, x, y):
        """Find the owner and the territories given a coordinate on
           the board

        Args:
            x (int): Column on the board
            y (int): Row on the board

        Returns:
            (str, set): A tuple, the first element being the owner
                        of that area.  One of "W", "B", "".  The
                        second being a set of coordinates, representing
                        the owner's territories.
        """
        if not self._in_bounds(x, y):
            raise ValueError("Invalid coordinate")

        stone = self.board[y][x]
        if stone != " ":
            return stone, set()

        region = self._flood(x, y)
        return self._owner(region), region

    def territories(self):
        """Find the owners and the territories of the whole board

        Args:
            none

        Returns:
            dict(str, set): A dictionary whose key being the owner
                        , i.e. "W", "B", "".  The value being a set
                        of coordinates owned by the owner.
        """
        result = {BLACK: set(), WHITE: set(), NONE: set()}
        seen = set()
        for y, row in enumerate(self.board):
            for x in range(len(row)):
                if (x, y) in seen or row[x] != " ":
                    continue
                region = self._flood(x, y)
                seen |= region
                result[self._owner(region)] |= region
        return result

